#include "platform/text_fonts.h"

#include <cctype>
#include <cstring>

namespace platform::text {

// The embedded faces (generated by platform/CMakeLists.txt from
// third_party/fonts/*.ttf, in the order of IWD2R_TEXT_FACES).
const Face* EmbeddedFaces(int* count);

namespace {

    // The faces, by number: the order of IWD2R_TEXT_FACES.
    enum FaceId {
        kBody = 0, // running text: dialog, descriptions, journal (NORMAL)
        kDisplay = 1, // headings and buttons, carved capitals (STONESML, STONESM2, STONEBIG)
        kLabel = 2, // small labels (TOOLFONT)
        kUncial = 3, // the uncial titles (REALMS)
    };

    struct Mapping {
        const char* resref;
        int face;
        float sizeFactor;
    };

    // Fonts not listed keep the bitmap glyphs: the drop caps (INITIALS),
    // symbol fonts (STATES2, WMDAG) and digit strips (NUMBER, NUMFONT).
    const Mapping kMappings[] = {
        { "NORMAL", kBody, 1.0f },
        { "STONESML", kDisplay, 1.0f },
        { "STONESM2", kDisplay, 1.0f },
        { "STONEBIG", kBody, 1.0f },
        { "TOOLFONT", kLabel, 1.0f },
        { "REALMS", kUncial, 1.0f },
    };

    bool SameResRef(const char* a, const char* b)
    {
        for (; *a != '\0' && *b != '\0'; a++, b++) {
            if (std::toupper(static_cast<unsigned char>(*a)) != std::toupper(static_cast<unsigned char>(*b)))
                return false;
        }
        return *a == '\0' && *b == '\0';
    }

    // Windows-1252's 0x80-0x9F; 0 for the five unassigned bytes.
    const uint16_t kHigh[32] = {
        0x20AC, 0, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021,
        0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0, 0x017D, 0,
        0, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
        0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0, 0x017E, 0x0178
    };

}

bool FaceFor(const char* resref, int* face, float* sizeFactor)
{
    if (resref == nullptr)
        return false;
    for (const Mapping& m : kMappings) {
        if (SameResRef(m.resref, resref)) {
            *face = m.face;
            *sizeFactor = m.sizeFactor;
            return true;
        }
    }
    return false;
}

const Face* FaceAt(int face)
{
    int count = 0;
    const Face* faces = EmbeddedFaces(&count);
    if (face < 0 || face >= count || faces[face].data == nullptr || faces[face].size == 0)
        return nullptr;
    return &faces[face];
}

int FaceCount()
{
    int count = 0;
    EmbeddedFaces(&count);
    return count;
}

uint16_t DecodeCp1252(uint8_t byte)
{
    if (byte >= 0x80 && byte < 0xA0) {
        const uint16_t cp = kHigh[byte - 0x80];
        return cp != 0 ? cp : byte;
    }
    return byte;
}

}
